+        onClick={handleToggle}
+        type="button"
+      >
+        <span className="min-w-0 flex-1 truncate text-left">
+          {activeOrganization?.name ?? "Select organization"}
+        </span>
+        <ChevronsUpDown className="size-4 shrink-0 text-muted-foreground" />
