1	import { mongodbAdapter } from "@better-auth/mongo-adapter";
2	import { betterAuth } from "better-auth";
3	import { nextCookies } from "better-auth/next-js";
4	import { organization } from "better-auth/plugins";
5	import { MongoClient, ObjectId } from "mongodb";
6	import { keys } from "./keys";
7	
8	// The better-auth server instance. One authority for the whole monorepo:
9	// apps/app mounts its handler at /api/auth/[...all]; everything else talks
10	// to it through the compat layer in server.ts or the client in client.ts.
11	//
12	// Guarded like @repo/knowledge/client rather than via `server-only`: this
13	// must import in any server runtime (Next.js, scripts, a future agent app),
14	// and server-only's react-server export condition throws outside React.
15	if (typeof window !== "undefined") {
16	  throw new Error(
17	    "@repo/auth/instance is server-side only and must not reach a browser bundle"
18	  );
19	}
20	
21	// The adapter maps ids to ObjectIds in storage but hands strings to hooks —
22	// reference fields must be matched in both forms.
23	export const idForms = (id: string) => ({
24	  $in: ObjectId.isValid(id) ? [id, new ObjectId(id)] : [id],
25	});
26	
27	const globalForAuth = global as unknown as { authMongo?: MongoClient };
28	
29	const client =
30	  globalForAuth.authMongo ??
31	  new MongoClient(process.env.MONGODB_URI ?? "mongodb://localhost:27017");
32	if (process.env.NODE_ENV !== "production") {
33	  globalForAuth.authMongo = client;
34	}
35	const db = client.db();
36	
37	export const authInstance = betterAuth({
38	  baseURL: keys().BETTER_AUTH_URL,
39	  // transaction: false — transactions need a replica set; Atlas has one but
40	  // local/standalone Mongo does not, and auth writes don't need multi-doc
41	  // atomicity badly enough to make the adapter environment-dependent.
42	  database: mongodbAdapter(db, { client, transaction: false }),
